# Lumina Tab - One-Liner Update Script
# Copia y pega todo esto en PowerShell (click derecho, pega)

$oldPath = Read-Host "Ruta de tu carpeta anterior de la extension (D:\...)"; if (-not (Test-Path $oldPath)) { Write-Host "Carpeta no existe" -ForegroundColor Red; exit }; Write-Host "OK: $oldPath" -ForegroundColor Green; $tempDir = Join-Path $env:TEMP "lumina-tab-temp"; if (Test-Path $tempDir) { Remove-Item $tempDir -Recurse -Force }; $gitOk = $null -ne (Get-Command git -ErrorAction SilentlyContinue); if ($gitOk) { git clone https://github.com/matijaime/lumina-tab.git $tempDir 2>&1 | Out-Null; if ($LASTEXITCODE -ne 0) { $gitOk = $false } }; if (-not $gitOk) { Write-Host "Descargando ZIP..." -ForegroundColor Cyan; [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12; $zip = Join-Path $env:TEMP "lumina.zip"; Invoke-WebRequest -Uri "https://github.com/matijaime/lumina-tab/archive/refs/heads/main.zip" -OutFile $zip -ErrorAction Stop; Expand-Archive -Path $zip -DestinationPath $tempDir -ErrorAction Stop; $extracted = Get-ChildItem $tempDir | Select-Object -First 1; if ($extracted.PSIsContainer) { $t2 = Join-Path $env:TEMP "lumina-temp2"; Move-Item $extracted.FullName $t2 -Force; Remove-Item $tempDir -Recurse -Force; Rename-Item $t2 $tempDir }; Remove-Item $zip -Force }; Write-Host "Respaldando..." -ForegroundColor Yellow; $backup = Join-Path (Split-Path $oldPath) "lumina-backup-$(Get-Date -Format 'yyyyMMdd-HHmmss')"; Copy-Item $oldPath $backup -Recurse -Force; Write-Host "OK: $backup" -ForegroundColor Green; Write-Host "Limpiando..." -ForegroundColor Yellow; Get-Item "$oldPath\*.js", "$oldPath\*.css", "$oldPath\*.html", "$oldPath\*.json", "$oldPath\background.js", "$oldPath\font-loader.js" -ErrorAction SilentlyContinue | Remove-Item -Force; Get-Item "$oldPath\icons" -ErrorAction SilentlyContinue | Remove-Item -Recurse -Force; Write-Host "Copiando archivos nuevos..." -ForegroundColor Yellow; Get-ChildItem $tempDir -Recurse | ForEach-Object { $rel = $_.FullName.Substring($tempDir.Length + 1); $skip = $false; foreach ($ex in @(".git", ".gitignore", "*.md", "*.txt", "ACTUALIZACIONES", "README", ".github")) { if ($rel -like "*$ex*") { $skip = $true; break } }; if (-not $skip) { $target = Join-Path $oldPath $rel; if ($_.PSIsContainer) { if (-not (Test-Path $target)) { New-Item $target -ItemType Directory -Force | Out-Null } } else { $tdir = Split-Path $target; if (-not (Test-Path $tdir)) { New-Item $tdir -ItemType Directory -Force | Out-Null }; Copy-Item $_.FullName $target -Force } } }; Remove-Item $tempDir -Recurse -Force -ErrorAction SilentlyContinue; Write-Host "`n================================" -ForegroundColor Green; Write-Host "LISTO! Actualizado:" -ForegroundColor Green; Write-Host "  $oldPath" -ForegroundColor Cyan; Write-Host "================================" -ForegroundColor Green; Write-Host "`nProximos pasos:" -ForegroundColor Yellow; Write-Host "1. Abre Chrome" -ForegroundColor White; Write-Host "2. Ve a chrome://extensions/" -ForegroundColor White; Write-Host "3. Busca 'Lumina Tab'" -ForegroundColor White; Write-Host "4. Haz clic en recarga (icono circular)" -ForegroundColor White; Write-Host "5. Abre una nueva pestana" -ForegroundColor White; Write-Host "`nTus datos se conservan automaticamente!" -ForegroundColor Green; Read-Host "`nPresiona Enter para cerrar"
